package pgn

import "fmt"

// The Const types and their enumerators below were generated long ago from
// the upstream schema's lookup enumerations by an out-of-tree tool -- this
// package has no in-repo generator for them (contrast the PGN struct files,
// each headed "Code generated by PGN generator; DO NOT EDIT.", which are
// regenerated from the same upstream metadata that backs upstream_definitions.go).
// Consequently this file is NOT refreshed as part of ongoing metadata sync,
// and it has already drifted from the LookupEnumeration names present in
// upstream_definitions.go: as of this writing dozens of LookupEnumeration
// names (e.g. several AGS_*, SIMNET_*, and WP_* lookups) have no matching
// Const type here.
//
// Drift is detected, not fixed, by the opt-in enum check in
// upstream_parity_test.go (TestEnumConstantsCoverLookupEnumerations, gated
// behind UPSTREAM_PARITY=1 like the rest of that file). See that test's doc
// comment for the exact <CamelCase>Const naming rule.

type LightingCommandConst uint8

const (
	Idle          LightingCommandConst = 0
	DetectDevices LightingCommandConst = 1
	Reboot        LightingCommandConst = 2
	FactoryReset  LightingCommandConst = 3
	PoweringUp    LightingCommandConst = 4
)

func (e LightingCommandConst) GoString() string { return e.String() }
func (e LightingCommandConst) String() string {
	switch e {
	case 0:
		return "Idle"
	case 1:
		return "Detect Devices"
	case 2:
		return "Reboot"
	case 3:
		return "Factory Reset"
	case 4:
		return "Powering Up"
	default:
		return fmt.Sprintf("%s(%d)", "LightingCommandConst", int(e))
	}
}

